import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
const methods=[['clip','clip'],['css-minde','cssMinde'],['oklch-cubic','oklchCubic'],['oklch-cubic-no-cache','oklchCubicNoCache'],['oklch-cubic-direct','oklchCubicDirect'],['oklch-halley','oklchHalley'],['oklch-ostrowski','oklchOstrowski'],['dualray','dualray'],['bottosson-lightness','bottossonLightness'],['bottosson-lightness','bottossonLightnessCached'],['edge-seeker/index','edgeSeeker'],['edge-seeker/index','edgeSeekerIndexed'],['raytrace','raytrace']];
const roots=['/tmp/gma-m4/before','/home/lloydk/work/gma-benchmark'];
const samples=[];
for(let l=1;l<100;l++)for(let h=0;h<360;h++)samples.push([l/100,.4,h]);
for(let i=0;i<35640;i++)samples.push([.01+.98*((i*.7548776662466927)%1),.4,(i*137.50776405003785)%360]);
for(let i=0;i<8192;i++)samples.push([.001+.998*((i*.7548776662466927)%1),.5*((i*.5698402909980532)%1),(i*137.50776405003785)%1080-360]);
const report=[];
for(const [file,name] of methods){
 const [a,b]=await Promise.all(roots.map(async r=>(await import(pathToFileURL(`${r}/src/${file}.js`)))[name]));
 const x=[],y=[];let count=0;
 for(const checked of [false,true])for(const input of samples){
  a(input,x,checked);b(input,y,checked);
  assert.deepEqual(y,x,`${name} checked=${checked} ${input}`);count++;
 }
 report.push({name,count,changed:0});
}
console.log(JSON.stringify({runtime:process.versions.node,bun:process.versions.bun,samples:samples.length,report},null,2));

initial_factory_experiment.initial_clip_source:
import { DISPLAY_P3 } from "./rgb-spaces.js";
import { createRgbConversions } from "./rgb-convert.js";

// The target is selected at setup. The returned mapper reuses the caller's out.
export function createClip (space) {
	const { oklchToClippedRgb } = createRgbConversions(space);
	return function clip (oklch, out) {
		return oklchToClippedRgb(oklch[0], oklch[1], oklch[2], out);
	};
}
export const clip = createClip(DISPLAY_P3);
